CREATE TABLE public.notebooks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,learner_id uuid NOT NULL REFERENCES public.learners(id) ON DELETE CASCADE,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.notebooks TO authenticated;GRANT ALL ON public.notebooks TO service_role;
ALTER TABLE public.notebooks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_notebooks ON public.notebooks FOR ALL TO authenticated USING(owner_user_id=auth.uid()) WITH CHECK(owner_user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.learners l WHERE l.id=learner_id AND l.owner_user_id=auth.uid()));
CREATE TABLE public.notebook_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,file_name text NOT NULL,storage_path text NOT NULL UNIQUE,mime_type text NOT NULL,file_size bigint NOT NULL CHECK(file_size BETWEEN 1 AND 10485760),processing_status text NOT NULL DEFAULT 'pending',processing_error text,uploaded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notebook_documents TO authenticated;GRANT ALL ON public.notebook_documents TO service_role;
ALTER TABLE public.notebook_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_documents ON public.notebook_documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.notebooks n WHERE n.id=notebook_id AND n.owner_user_id=auth.uid()));
CREATE TABLE public.document_chunks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),document_id uuid NOT NULL REFERENCES public.notebook_documents(id) ON DELETE CASCADE,chunk_index integer NOT NULL,content text NOT NULL,page_number integer,UNIQUE(document_id,chunk_index));
GRANT SELECT ON public.document_chunks TO authenticated;GRANT ALL ON public.document_chunks TO service_role;
ALTER TABLE public.document_chunks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_chunks ON public.document_chunks FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.notebook_documents d JOIN public.notebooks n ON n.id=d.notebook_id WHERE d.id=document_id AND n.owner_user_id=auth.uid()));
CREATE TABLE public.ai_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),notebook_id uuid NOT NULL REFERENCES public.notebooks(id) ON DELETE CASCADE,role text NOT NULL CHECK(role IN ('user','assistant')),content text NOT NULL,source_references jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.ai_messages TO authenticated;GRANT ALL ON public.ai_messages TO service_role;
ALTER TABLE public.ai_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_messages ON public.ai_messages FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.notebooks n WHERE n.id=notebook_id AND n.owner_user_id=auth.uid()));
CREATE TABLE public.ai_usage(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_usage TO service_role;ALTER TABLE public.ai_usage ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.ai_access_state(id text PRIMARY KEY,paused boolean NOT NULL DEFAULT false,reason text NOT NULL DEFAULT '',kind text NOT NULL DEFAULT '',updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.ai_access_state TO service_role;ALTER TABLE public.ai_access_state ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.reserve_tutor_request(p_user uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM 1 FROM public.profiles WHERE id=p_user FOR UPDATE; IF EXISTS(SELECT 1 FROM public.ai_access_state WHERE id='tutor' AND paused) THEN RETURN false; END IF; IF (SELECT count(*) FROM public.ai_usage WHERE user_id=p_user AND created_at>=date_trunc('day',now()))>=20 THEN RETURN false; END IF; INSERT INTO public.ai_usage(user_id) VALUES(p_user); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.reserve_tutor_request(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.reserve_tutor_request(uuid) TO service_role;
CREATE TABLE public.devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,learner_id uuid REFERENCES public.learners(id),device_uid text UNIQUE NOT NULL,name text NOT NULL,firmware_version text,last_seen_at timestamptz,status text NOT NULL DEFAULT 'offline',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.devices TO authenticated;GRANT ALL ON public.devices TO service_role;ALTER TABLE public.devices ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_devices ON public.devices FOR SELECT TO authenticated USING(owner_user_id=auth.uid());
CREATE TABLE public.device_pairing_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,code_hash text NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.device_pairing_requests TO authenticated;GRANT ALL ON public.device_pairing_requests TO service_role;ALTER TABLE public.device_pairing_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_pairings ON public.device_pairing_requests FOR SELECT TO authenticated USING(owner_user_id=auth.uid());
CREATE TABLE public.device_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid NOT NULL REFERENCES public.devices(id) ON DELETE CASCADE,event_type text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.device_events TO authenticated;GRANT ALL ON public.device_events TO service_role;ALTER TABLE public.device_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_device_events ON public.device_events FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.devices d WHERE d.id=device_id AND d.owner_user_id=auth.uid()));
CREATE INDEX documents_notebook ON public.notebook_documents(notebook_id);CREATE INDEX chunks_document ON public.document_chunks(document_id);CREATE INDEX messages_notebook ON public.ai_messages(notebook_id,created_at);CREATE INDEX ai_usage_user_date ON public.ai_usage(user_id,created_at);
COMMENT ON COLUMN public.lessons.content IS 'Version 1: intro, goal, hints array, optional planets array of name/detail. Validate through sceneSchema.';